"""MCP-facing tool surface. Thin delegation to a Broker.

Bind these methods as MCP tools in any runtime; they take and return
plain JSON-compatible structures so an agent can call them directly.
"""
from __future__ import annotations

from ohtp.broker import Broker
from ohtp.envelope import TaskEnvelope


class OhtpTools:
    def __init__(self, broker: Broker) -> None:
        self._broker = broker

    def post_task(self, envelope: dict) -> dict:
        return {"id": self._broker.post(TaskEnvelope(**envelope))}

    def list_open_tasks(self) -> list:
        return self._broker.list_open()

    def get_task(self, task_id: str, requester: str = "worker") -> dict:
        return self._broker.get(task_id, requester)

def test_package_imports():
    import ohtp

    assert ohtp.__doc__ is not None

from ohtp.envelope import EvidenceField
from ohtp.evidence import EvidenceItem, validate_bundle


def test_missing_field_reported():
    schema = [EvidenceField(name="photo", kind="geo_photo")]
    errors = validate_bundle({}, schema)
    assert errors == ["missing evidence field: photo"]


def test_wrong_kind_reported():
    schema = [EvidenceField(name="photo", kind="geo_photo")]
    bundle = {"photo": EvidenceItem(kind="otp_echo", data={})}
    errors = validate_bundle(bundle, schema)
    assert errors == ["field photo: expected kind geo_photo, got otp_echo"]


def test_structured_json_validated_against_schema():
    schema = [
        EvidenceField(
            name="receipt",
            kind="structured_json",
            json_schema={
                "type": "object",
                "required": ["amount"],
                "properties": {"amount": {"type": "number"}},
            },
        )
    ]
    ok = {"receipt": EvidenceItem(kind="structured_json", data={"amount": 5})}
    bad = {"receipt": EvidenceItem(kind="structured_json", data={})}
    assert validate_bundle(ok, schema) == []
    assert validate_bundle(bad, schema) == [
        "field receipt: json schema validation failed"
    ]


def test_all_valid_returns_empty():
    schema = [EvidenceField(name="photo", kind="geo_photo")]
    bundle = {"photo": EvidenceItem(kind="geo_photo", data={"lat": 1})}
    assert validate_bundle(bundle, schema) == []
